  AgeCalc(formName) {
    debugger
    let calcage: any = 0;
    let dob = new Date(this[formName].value.dob);
    let currDate = new Date();
    var diff = currDate.getTime() - dob.getTime();
    calcage = Math.floor(diff / (1000 * 60 * 60 * 24 * 365.25));
    this[formName].patchValue({
      age: calcage
    })
  }

